750	    match kind {
751	        LineKind::Added => Style::default().fg(Color::Green),
752	        LineKind::Removed => Style::default().fg(Color::Red),
753	        LineKind::Hunk => Style::default().fg(Color::Cyan),
754	        LineKind::Meta => Style::default().fg(MUTED),
755	        LineKind::Command => Style::default()
