762	/// How a row of a command's `diff` output is coloured: rows that are not part of a hunk read as headers.
763	fn diff_row_kind(row: &str) -> LineKind {
764	    if row.starts_with('+') && !row.starts_with("+++") {
765	        LineKind::Added
766	    } else if row.starts_with('-') && !row.starts_with("---") {
767	        LineKind::Removed
768	    } else if row.starts_with("@@") {
769	        LineKind::Hunk
770	    } else if row.starts_with(' ') {
771	        LineKind::Context
772	    } else {
773	        LineKind::Meta
774	    }
775	}
