779	/// Slash-command completion: up to six rows at the bottom of the transcript area, the highlighted one in accent.
780	fn render_completion(frame: &mut Frame, area: Rect, found: &[&SlashSpec], pick: usize) {
781	    let shown = found
782	        .len()
783	        .min(MAX_COMPLETION_ROWS)
784	        .min(usize::from(area.height));
785	    if shown == 0 {
786	        return;
787	    }
788	    let first = (pick + 1).saturating_sub(shown);
789	    let width = found
790	        .iter()
791	        .map(|spec| spec.usage.chars().count())
792	        .max()
793	        .unwrap_or(0)
794	        .min(40);
795	    let lines: Vec<Line> = found
796	        .iter()
797	        .enumerate()
798	        .skip(first)
799	        .take(shown)
800	        .map(|(index, spec)| {
801	            let style = if index == pick {
802	                Style::default().fg(Color::Black).bg(ACCENT)
803	            } else {
804	                Style::default().fg(Color::White).bg(SURFACE)
805	            };
806	            let position = if index == pick { format!(" {}/{} ", pick + 1, found.len()) } else { String::new() };
807	            let room = usize::from(area.width).saturating_sub(width + 4 + position.chars().count());
808	            let summary = diff_view::clip(&spec.summary, room);
809	            let pad = room.saturating_sub(unicode_width::UnicodeWidthStr::width(summary.as_str()));
810	            Line::from(vec![
811	                Span::styled(format!(" {:<width$}  {summary}{}", spec.usage, " ".repeat(pad)), style),
812	                Span::styled(position, if index == pick { style.add_modifier(Modifier::BOLD) } else { style }),
813	            ])
814	        })
815	        .collect();
816	    let height = u16::try_from(shown).unwrap_or(0);
817	    let rect = Rect::new(area.x, area.bottom() - height, area.width, height);
818	    frame.render_widget(Clear, rect);
819	    frame.render_widget(
820	        Paragraph::new(lines).style(Style::default().bg(SURFACE)),
821	        rect,
822	    );
823	}
