        vec![
            Span::styled(diff_view::safe_text(&tool_verb(&approval.tool)), Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
            Span::styled(format!(" {}", diff_view::safe_text(&approval.subject)), Style::default().fg(Color::White)),
        ],
        width,
        Vec::new(),
        vec![Span::raw("  ")],
