        None => approval
            .lines
            .iter()
            .flat_map(|line| markdown::wrap(vec![Span::styled(expand_tabs(&line.text).into_owned(), line_style(line.kind))], width, Vec::new(), vec![Span::raw("    ")]))
            .collect(),
