403	
404	/// The visible stand-in for a character a terminal would interpret: control pictures for C0 controls (`␛` for ESC),
405	/// `␡` for DEL, `<U+XXXX>` for C1 controls, bidirectional overrides, zero-width, no-break and other space characters, soft hyphens, variation selectors, tag characters and line/paragraph separators. `None` for ordinary characters.
406	pub fn visible_control(c: char) -> Option<String> {
407	    let code = c as u32;
408	    match code {
409	        0x00..=0x1f => char::from_u32(0x2400 + code).map(String::from),
410	        0x7f => Some("␡".to_string()),
411	        0x80..=0xa0 | 0xad | 0x34f | 0x61c | 0x115f | 0x1160 | 0x1680 | 0x180b..=0x180e | 0x2000..=0x200f | 0x2028..=0x202f | 0x205f..=0x2064
412	        | 0x2066..=0x2069 | 0x3000 | 0x3164 | 0xfe00..=0xfe0f | 0xfeff | 0xffa0 | 0xfff9..=0xfffb | 0xe0000..=0xe007f | 0xe0100..=0xe01ef => Some(format!("<U+{code:04X}>")),
413	        _ => None,
414	    }
415	}
