417	/// Text safe to draw: every control character replaced by its visible stand-in (tabs and newlines included).
418	pub fn safe_text(text: &str) -> String {
419	    let mut out = String::with_capacity(text.len());
420	    for c in text.chars() {
421	        match visible_control(c) {
422	            Some(stand_in) => out.push_str(&stand_in),
423	            None => out.push(c),
424	        }
425	    }
426	    out
427	}
