429	fn cells(text: &str, lang: Option<&Lang>) -> Vec<Cell> {
430	    let tokens = lang.map(|lang| highlight::highlight(lang, text)).unwrap_or_default();
431	    let mut token_at = tokens.iter().peekable();
432	    let mut out: Vec<Cell> = Vec::new();
433	    let mut col = 0;
434	    for (offset, grapheme) in text.grapheme_indices(true) {
435	        while token_at.peek().is_some_and(|(_, end, _)| *end <= offset) {
436	            token_at.next();
437	        }
438	        let token = token_at.peek().map_or(Token::Plain, |(_, _, t)| *t);
439	        if grapheme == "\t" {
440	            let spaces = TAB - col % TAB;
441	            for _ in 0..spaces {
442	                out.push(Cell { text: " ".into(), width: 1, token: Some(token) });
443	            }
444	            col += spaces;
445	            continue;
446	        }
447	        if grapheme.chars().any(|c| visible_control(c).is_some()) {
448	            for c in grapheme.chars() {
449	                let shown = visible_control(c).unwrap_or_else(|| c.to_string());
450	                for piece in shown.chars() {
451	                    let width = UnicodeWidthStr::width(piece.to_string().as_str()).max(1);
452	                    out.push(Cell { text: piece.to_string(), width, token: Some(token) });
453	                    col += width;
454	                }
455	            }
456	            continue;
457	        }
458	        let width = UnicodeWidthStr::width(grapheme);
459	        if width == 0 {
460	            match out.last_mut() {
461	                Some(previous) => previous.text.push_str(grapheme),
462	                None => out.push(Cell { text: grapheme.to_string(), width: 0, token: Some(token) }),
463	            }
464	            continue;
465	        }
466	        out.push(Cell { text: grapheme.to_string(), width, token: Some(token) });
467	        col += width;
468	    }
469	    out
470	}
