481	/// Splits content cells into rows of at most `width` columns. Wrapping breaks after a space when one falls in the
482	/// latter two thirds of the row (the space stays at the row's end, so no character is lost), else at the edge.
483	fn fit_rows(cells: Vec<Cell>, width: usize, fit: Fit) -> Vec<Vec<Cell>> {
484	    match fit {
485	        Fit::Wrap => {
486	            let mut rows: Vec<Vec<Cell>> = vec![Vec::new()];
487	            let mut used = 0;
488	            for cell in cells {
489	                if used + cell.width > width && used > 0 {
490	                    let row = rows.last_mut().expect("a row is open");
491	                    let mut carried = Vec::new();
492	                    if cell.text != " " {
493	                        let mut at = 0;
494	                        let mut space = None;
495	                        for (index, c) in row.iter().enumerate() {
496	                            at += c.width;
497	                            if c.text == " " && at * 3 > width {
498	                                space = Some(index);
499	                            }
500	                        }
501	                        if let Some(index) = space {
502	                            carried = row.split_off(index + 1);
503	                        }
504	                    }
505	                    used = carried.iter().map(|c| c.width).sum();
506	                    rows.push(carried);
507	                }
508	                used += cell.width;
509	                rows.last_mut().expect("a row is open").push(cell);
510	            }
511	            rows
512	        }
513	        Fit::Clip(left) => {
514	            let total: usize = cells.iter().map(|c| c.width).sum();
515	            let right = left + width;
516	            let mut row = Vec::new();
517	            let mut col = 0;
518	            for cell in cells {
