        let forbidden = |c: char| c.is_control() || matches!(c as u32, 0x202a..=0x202e | 0x2066..=0x2069 | 0x200b..=0x200f | 0xe0000..=0xe007f | 0xa0 | 0x2062 | 0xfe0f | 0x3000);
        for (index, request) in requests.iter().enumerate() {
